# owner: platform
"""Snap span edges to a clock step, then label them."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span


def _check_step(step: int) -> None:
    if step <= 0 or 60 % step != 0:
        raise ValueError(f"step must divide 60: {step}")


def _round_minute(minute: int, step: int) -> int:
    """Nearest multiple of step, halves round up."""
    return (minute + step // 2) // step * step


def _round_span(span: Span, step: int) -> Span:
    start = _round_minute(span.start, step)
    return Span(start, _round_minute(span.end, step))


def _label(span: Span) -> str:
    hours, minutes = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {minutes}m)"


# ---
def label_rounded_spans(
    spans: Iterable[Span], step: int
) -> List[str]:
    """Round each span to the step, then label it."""
    _check_step(step)
    rounded = [_round_span(span, step) for span in spans]
    return [_label(span) for span in rounded]
